/**
 * Every line anyone says.
 *
 * Generated by tools/assemble-dialogue.ts from src/data/dialogue.parts/*.json. Edit the JSON, not this
 * file. The brief the writers worked to is docs/BEATS.md.
 *
 * Conventions: node ids are `<npc>-<slot>`. `next` chains without input; `choices` are the only branch
 * points, never more than two. Pip speaks as 'pip' — lowercase, terse, a little deadpan.
 */

import type { DialogueChoice, DialogueNode } from '../core/contracts';

const c = (text: string, next: string, takes?: boolean): DialogueChoice => (takes ? { text, next, takes } : { text, next });
type Opt = { next?: string; choices?: DialogueChoice[]; fill?: string };
const n = (id: string, speaker: string, lines: string[], o: Opt = {}): DialogueNode => ({
  id,
  speaker,
  lines,
  ...o,
});

export const DIALOGUE: Readonly<Record<string, DialogueNode>> = {
  'nana-root': n('nana-root', 'nana', ["There you are. Let me look at you. Thinner. The road does that.","Bad timing, love. The radio's gone quiet. Not a word since Tuesday.","The set's up at the mast on Brindle Peak, dead for want of power.","Bram, who keeps the woodstore by the big pine, has spare batteries.","And take my old camera. Edda, who keeps the set up there, has been after one for weeks. She'll tell you why."], { choices: [c("i'll get them from bram.", 'nana-errand', true), c("why can't the radio wait?", 'nana-chat')] }),
  'nana-chat': n('nana-chat', 'nana', ["Because the snow's early, and when it comes the road closes behind it.","The radio is how the valley checks on itself. Orla's flour, Skiff's ice, whose chimney's gone cold.","Edda keeps the set at the mast. She's sat with a dead box since.","I'd go myself. These knees did that climb sixty winters. They're done."], { next: 'nana-errand' }),
  'nana-errand': n('nana-errand', 'nana', ["Bram is the red squirrel with the woodstore, just up by the big pine.","He'll want something done first. He always does. Do it his way.","Then bring the batteries here, and I'll tell you the rest."]),
  'nana-wait': n('nana-wait', 'nana', ["Still empty-handed? Don't fret. It's early yet.","Bram keeps the batteries in his woodstore, by the big pine.","He's particular, not mean. Whatever he asks, it'll be quick and it'll be fussy.","Bring them straight here. Not up the hill. Here."]),
  'nana-done': n('nana-done', 'nana', ["You got them off him. Heavy, aren't they? That's the radio's voice in there.","Here. Take my lantern. There are posts all along the trail. Light them as you pass.","Lit, they'll show you the way back down to me.","Edda keeps the set at the mast. Give these to her and nobody else."], { choices: [c("what's edda like?", 'nana-edda'), c("i'll go now.", 'nana-send')] }),
  'nana-edda': n('nana-edda', 'nana', ["Edda is an owl. Proud, kind, and she can't abide a fuss.","We've talked on that set every evening for thirty years.","She'll ask if I'm well. Tell her yes. She'll pretend she wasn't worried."], { next: 'nana-send' }),
  'nana-send': n('nana-send', 'nana', ["Climb slow. The wind up there will have the feathers off you if you let it.","And when it's done, come back down. I'll want to hear it from you."]),
  'nana-climb-wait': n('nana-climb-wait', 'nana', ["Still here? Those batteries won't do much at the bottom of the hill, love.","Up through Windscar Ridge. Light the trail posts as you pass them.","Edda keeps the set at the mast on Brindle Peak. She's waiting on you.","Go on. I'm not going anywhere, and neither is the cabin."]),
  'nana-letter': n('nana-letter', 'nana', ["A letter? From Pell, the postmaster, all the way across the valley?","'The blue house, road head.' Well, that's me. I painted it again in autumn, so there'd be no doubt.","Hm. I'll need to read that again. And again, probably.","This one stays by the stove. Tell Pell it found the right door, love. He frets."]),
  'nana-home-done': n('nana-home-done', 'nana', ["There you are. I heard you on the radio. The whole valley did."], { next: 'nana-home-posts' }),
  'nana-home-posts': n('nana-home-posts', 'nana', ["Edda says you did her looking for her. She sounded twenty winters younger.","Now. Tell me one thing. Just one, tonight. I'll have the rest out of you tomorrow."], { choices: [c("bram's pile is four hundred and eighty-one.", 'nana-home-wood'), c("the sky went green over the peak.", 'nana-home-sky')], fill: 'nana-posts' }),
  'nana-home-wood': n('nana-home-wood', 'nana', ["I know. He told the whole valley on the radio. Then he told it again.","He'll count it tonight, twice. First night in years he'll like the answer."], { next: 'nana-home-close' }),
  'nana-home-sky': n('nana-home-sky', 'nana', ["The lights? Of course. Edda never could see the green. Now she knows it's there.","Was it as bright as they say? No, don't tell me. I'll picture it."], { next: 'nana-home-close' }),
  'nana-home-close': n('nana-home-close', 'nana', ["Sit out here with me a minute, then. I want to look at those posts.","The valley will be there in the morning. All of it. All of them.","And Pip. I'm glad it was you that went up."], { fill: 'nana-heard' }),
  'nana-idle': n('nana-idle', 'nana', ["Sit a minute and get warm. Whatever's out there will keep.","There's always a cup in this house for you. You know where they live.","Go on when you're ready. The valley's still yours to walk."]),
  'hollis-root': n('hollis-root', 'hollis', ["You're Nana's. The one come up the road.","I've lost a mitten. The left one. The good one.","I know who took it. Fen, the owl who watches from the pines.","Go ask him. See what he says."], { choices: [c("i'll ask fen.", 'hollis-wait', true), c("why would fen take a mitten?", 'hollis-chat')] }),
  'hollis-chat': n('hollis-chat', 'hollis', ["He's an owl. He watches. He's got them big eyes.","And he never says anything. Guilty, if you ask me.","The pines. Creek side. That's where he sits.","Go on. Ask him."], { next: 'hollis-wait' }),
  'hollis-wait': n('hollis-wait', 'hollis', ["Ask him direct. Fen, the owl in the pines, won't volunteer a thing.","Drop a line in the creek pool below the split pine, too. In case he dropped it in, flying off.","Come back and tell me what he said."]),
  'hollis-done': n('hollis-done', 'hollis', ["You fished it out of the creek? Below the split pine?","So it wasn't Fen. The wind. Huh.","I'll have to say something to him. Eventually.","Here. My spare. One mitten's no use to me. Don't argue, I don't want to owe you."]),
  'hollis-idle': n('hollis-idle', 'hollis', ["The mitten's back on its hook, where it belongs.","I said sorry to Fen, the owl. Took me three tries. He nodded.","Wind's picking up. Keep your ears tucked in, Nana's girl."]),
  'hollis-fit': n('hollis-fit', 'hollis', ["A headband? From Tamsin, the marten in the pines? For me?","...Tight round the ears. But it holds. And it's warm. Don't tell anyone I said warm.","Tell her it fits. And tell her she could have just asked me."]),
  'bram-batteries': n('bram-batteries', 'bram', ["Four hundred and... no. That one's sticking out. Start again.","Batteries. Nana sent you. They're in the woodstore, behind that heap.","The end of the pile came down. No end, the rows lean, and I can't count a leaning row. Put it back and they're yours."], { choices: [c("why does it have to be straight?", 'bram-why'), c("fine. i'll stack it.", 'bram-how')] }),
  'bram-why': n('bram-why', 'bram', ["A straight pile, you count the rows. A crooked one, you count every log. Three times today. Three numbers.","Can't go into winter with three numbers. Winter wants one."], { next: 'bram-how' }),
  'bram-how': n('bram-how', 'bram', ["Eight logs, square across each other. I'll know if you've cheated. I'll count."]),
  'bram-stack': n('bram-stack', 'bram', ["Still a heap. I can see it from here.","Eight logs, square across each other. Then come and tell me."]),
  'bram-paid': n('bram-paid', 'bram', ["Let me count. Four hundred and seventy-three in the rows. Eight on the end. Yours.","Four hundred and eighty-one. Twice running. Do you know how long it's been?","Here. The spare batteries. Mind them, they're the only ones in the valley."], { next: 'bram-rope' }),
  'bram-rope': n('bram-rope', 'bram', ["And since you're going up: the bridge rope on Windscar Ridge is going. Everyone knows it.","Tuck, the marten who keeps that bridge, hasn't spoken to me in years. He won't come down and ask.","So take the good rope. Forty feet, coiled, no splices. I checked.","Tell Tuck I want it back the same length. I'll measure."]),
  'bram-rope-wait': n('bram-rope-wait', 'bram', ["The rope's still in your bag? It's for Tuck, at the bridge on Windscar Ridge. It's on your way up."]),
  'bram-rope-done': n('bram-rope-done', 'bram', ["It's tied? He took it? From me?","Still forty feet, he says. Come up and measure it, he says.","And what's that, bent at the bow? Give it here. That's my woodshed key.","I stood on it the winter we stopped talking. He's kept it tied in his rope all this time.","Well. Come spring I'll walk up there with my tape. Somebody has to check."]),
  'bram-idle': n('bram-idle', 'bram', ["Four hundred and seventy-nine, eighty, eighty-one. Right. From the top. Don't talk, I'm counting.","Wood's the one thing in this valley that stays counted. I like that.","People don't. People keep changing their numbers.","Go on. Mind the pile on your way past."]),
  'edda-early': n('edda-early', 'edda', ["A visitor, up here? You've climbed a long way to see a dead set.","I keep the radio at this mast. The whole valley talks through it.","Talked. It's dead for want of power. I'm waiting on batteries from below.","Nana Quill, at the cabin, is seeing to it. Tell her I'm still here."]),
  'edda-meet': n('edda-meet', 'edda', ["You'll be Nana's Pip. I'd know that lantern anywhere. And those are my batteries.","There. Hear the hum? The set's warm. But it only reaches the valley when the aurora's up."], { next: 'edda-ask' }),
  'edda-ask': n('edda-ask', 'edda', ["Here's my trouble. I'm an owl. I see the night in greys.","Three nights I've called on a bright cloud. Orla, Skiff, Wren, little Gus by his bell: nobody heard.","Nana's camera sees green. I don't.","Catch the aurora in a photograph, and tell me the moment it's up."], { choices: [c("where do i look?", 'edda-look'), c("what if it doesn't come?", 'edda-ifnot')] }),
  'edda-look': n('edda-look', 'edda', ["North, over the shoulder of the peak. It starts low, like a stain. Let it climb.","Then come straight to me. It doesn't stay long."]),
  'edda-ifnot': n('edda-ifnot', 'edda', ["Then we wait another night. But the snow's coming, and the road shuts with it.","Look north, over the shoulder of the peak. Then come straight to me."]),
  'edda-wait': n('edda-wait', 'edda', ["The set's warm and my talon's on the dial. The rest is the sky's.","North, over the shoulder of the peak. Green, low at first, then climbing. Get it on the camera, then tell me."]),
  'edda-line-up': n('edda-line-up', 'edda', ["It's up? Then here we go. Stand by me.","Brindle Peak calling the valley. Brindle Peak calling. Anyone there? Over.","Nothing. Static. The sky has to find us first. Give it a...","There."], { next: 'edda-line-bram' }),
  'edda-line-bram': n('edda-line-bram', 'bram', ["Hearth Hollow, by the big pine. Woodstore's full. Four hundred and eighty-one. Over."], { next: 'edda-line-orla' }),
  'edda-line-orla': n('edda-line-orla', 'orla', ["This is the bakery in Hollowpine Hamlet. The oven's on, and there's soup. Over."], { next: 'edda-line-skiff' }),
  'edda-line-skiff': n('edda-line-skiff', 'skiff', ["Boathouse on the Frozen Reach. The ice is holding. Lake's quiet. Over."], { next: 'edda-line-ivy' }),
  'edda-line-ivy': n('edda-line-ivy', 'ivy', ["Anyone cold, come down. Over."], { next: 'edda-line-wren', fill: 'ivy-radio' }),
  'edda-line-wren': n('edda-line-wren', 'wren', ["Wren, in Pinewind Wood. The mast's humming again. I can hear it from here. Over."], { next: 'edda-line-gus' }),
  'edda-line-gus': n('edda-line-gus', 'gus', ["Gus here, at the bell shop in the hamlet! I'm holding the big bell's rope!","Next time you call, I'll ring it. I will. Over."], { next: 'edda-line-pass' }),
  'edda-line-pass': n('edda-line-pass', 'edda', ["Hear that, faint, under the rest? That's the road crew, below the pass.","They're bringing the plough up in the morning. The road stays open."], { next: 'edda-line-nana' }),
  'edda-line-nana': n('edda-line-nana', 'nana', ["Edda, is that you? Is Pip up there with you?","Oh, good. That's good. Don't tell me anything. I want it from her.","And everyone along the trail: if there's a post near you, light it. She'll be coming down in the dark."], { next: 'edda-line-end' }),
  'edda-line-end': n('edda-line-end', 'edda', ["That's the valley, and the line holding.","Thirty winters I've kept this set. Never heard it so crowded.","Go on home, Pip. Follow the lights down.","I'll mind the set. Brindle Peak, over and out."], { fill: 'radio-unmet' }),
  'edda-idle': n('edda-idle', 'edda', ["The line's holding. They've not stopped talking since.","Bram, down by the big pine, has read me his count four times.","Give Nana my love. She'll pretend she doesn't need it.","Mind the ridge on the way down. The wind's in a mood tonight."]),
  'wren-root': n('wren-root', 'wren', ["You're Nana's Pip. She said you'd come up the valley before the snow.","I'm Wren. I write what the valley sounds like: springs, ice, pines knocking.","The book's nearly full. One page left, and nothing worth putting on it."], { choices: [c("what's wrong with the page?", 'wren-chat'), c("what would be worth writing?", 'wren-errand')] }),
  'wren-chat': n('wren-chat', 'wren', ["It's not the page. It's me. Everything sounds like something I've already written.","My very first page was the mast on Brindle Peak, humming in the cold. I was younger than you.","It's been quiet since Tuesday. I didn't know you could miss a hum."], { next: 'wren-errand' }),
  'wren-errand': n('wren-errand', 'wren', ["So listen for me. Fresh ears. Go to the hoarfrost glade and take a photograph.","Holding still for a picture is the only time anyone really listens. You'll hear the frost.","Then go down to Kettle Springs and stand among the hot pools. Nothing sounds like that water.","Then come back and tell me what you heard. I'll put it on the last page."]),
  'wren-wait': n('wren-wait', 'wren', ["You're back. The hoarfrost glade first. Hold still for the picture, and listen.","Then stand among the hot pools at Kettle Springs. Then come and tell me."]),
  'wren-still': n('wren-still', 'wren', ["The glade first, for the frost. Then the hot pools at Kettle Springs. Then me."]),
  'wren-done': n('wren-done', 'wren', ["You've been to both. Go on, then. What did you hear?"], { next: 'wren-pip' }),
  'wren-pip': n('wren-pip', 'pip', ["the frost in the glade ticks. like a stove cooling.","the springs sound like a kettle arguing with itself."], { next: 'wren-write' }),
  'wren-write': n('wren-write', 'wren', ["A stove cooling. A kettle arguing with itself. Oh, that's it exactly.","I'd stopped hearing both. That's the last page. The book's full.","Take it. I'll start a new one tomorrow, with my ears washed out."]),
  'tamsin-root': n('tamsin-root', 'tamsin', ["Oh. Mind the needles, they get everywhere. I'm Tamsin. I knit.","This is a headband for the hare by the road head. His ears go flat with cold.","I've never measured him. I didn't like to ask. So it might not fit at all."], { choices: [c("why not ask him?", 'tamsin-chat'), c("how will you know it fits?", 'tamsin-errand')] }),
  'tamsin-chat': n('tamsin-chat', 'tamsin', ["Walk up to a hare and ask him to hold still while I measure his ears? I'd sooner knit in the dark.","So I guess. I always guess. Would you help me find out if I guessed right?"], { next: 'tamsin-errand' }),
  'tamsin-errand': n('tamsin-errand', 'tamsin', ["He lives by the road head, in Hearth Hollow. Hollis, he's called.","Take it to him and ask him to try it on. I'd only fret.","But have a go at the pinecone toss first. Hit or miss. I like watching someone else be bad at something.","Then come back and tell me if it fits. Honestly. I'd rather know."]),
  'tamsin-wait': n('tamsin-wait', 'tamsin', ["You're still at it? The pinecone toss first. Hit or miss, I don't mind.","Then Hollis, the hare by the road head. Ask him to try it on.","If it's too tight, tell me true. I'd rather know."]),
  'tamsin-done': n('tamsin-done', 'tamsin', ["It fits? Tight on the ears, but it fits? Oh, thank goodness.","Then the next one gets more room round the ears. Keep this one. It was practice.","And next time I'll ask him myself. Out loud."]),
  'fen-root': n('fen-root', 'fen', ["You're up early. Or late. Hard to tell from a pine.","I watch the pines. Everything that moves through here goes in my tally. Nearly everything."], { choices: [c("what's missing?", 'fen-errand'), c("why keep a tally?", 'fen-chat')] }),
  'fen-chat': n('fen-chat', 'fen', ["The wood is all comings and goings. Somebody should keep track. It isn't prying if you write it down.","Most folk talk around an owl, hoping he'll fill in the rest. I don't."], { next: 'fen-errand' }),
  'fen-errand': n('fen-errand', 'fen', ["From this branch I see the creek. Up the hill there's a deer trail, and the trees hide it from me.","Something goes down that trail every day. I see it go in at the top. I never see what it is.","Run the trail, fast, and you'll see where it bends: past the glade and the split pine.","Tamsin, the marten who knits by the split pine, sits at the bend. Ask her what comes past."]),
  'fen-wait': n('fen-wait', 'fen', ["You're back. Run the deer trail, fast. See where it bends.","Then ask Tamsin, by the split pine, what comes down it. Then tell me."]),
  'fen-still': n('fen-still', 'fen', ["The deer trail first, fast. Then Tamsin, by the split pine. She sees what comes past."]),
  'fen-done': n('fen-done', 'fen', ["A roe deer? From the glade, down to drink at the creek, every morning?","There. That's the last line in the tally.","Twenty winters I've watched this wood. I could have asked the marten next door any day."]),
  'ilsa-root': n('ilsa-root', 'ilsa', ["You're Pip. Nana's told me about you. Don't stand still, you'll freeze.","I'm Ilsa. I carry things. Firewood, parcels, whatever wants carrying.","This one's for my sister. We had words, and I'd rather not be the one to carry it over."], { choices: [c("what were the words about?", 'ilsa-chat'), c("where am i taking it?", 'ilsa-errand')] }),
  'ilsa-chat': n('ilsa-chat', 'ilsa', ["She says I carry everyone's load and then sulk that nobody carries mine.","I say she sits in her steam and waits for people to come to her.","We're both right. That's the worst way to have a row."], { next: 'ilsa-errand' }),
  'ilsa-errand': n('ilsa-errand', 'ilsa', ["My sister Ivy keeps the hot pools at Kettle Springs, down the valley.","Put it in her hands, not on the step. She'll say I should have come myself.","Don't argue with her. Just come back and tell me it landed."]),
  'ilsa-wait': n('ilsa-wait', 'ilsa', ["Still carrying it? Good. Ivy, my sister, is at the pools, in the steam.","If she starts, don't argue. Hand it over and say it's from me."]),
  'ilsa-done': n('ilsa-done', 'ilsa', ["It landed? She took it?","And she said to come down myself. Of course she did.","Then tomorrow I'll go down. Carrying nothing. I'll let her feed me.","Sit a minute first. No, sit. I'm practising."]),
  'fen-mitten': n('fen-mitten', 'fen', ["You asked me straight out. Hardly anyone does. Most hint and hope.","I saw it. Hollis, the hare, hung it on a low branch to dry.","Wind took it into the creek pool below the split pine. Fish there and you'll hook it.","I didn't take it. Tell him that. He's been thinking it for two days."]),
  'tamsin-trail': n('tamsin-trail', 'tamsin', ["Fen, the owl, wants to know what uses the deer trail? He could have asked me.","It's the roe deer from the hoarfrost glade. She comes past my stump every morning, down to the creek to drink.","Tell him that. And tell him he's allowed to come and ask himself."]),
  'wren-idle': n('wren-idle', 'wren', ["I've started a new book. I write slower now. I listen longer first.","Listen. That knocking is the pines in the cold. I'd stopped hearing it.","If you hear something I haven't, come and tell me. I'll write it down."]),
  'tamsin-idle': n('tamsin-idle', 'tamsin', ["I'm knitting another. Measured, this time. I asked the hare to hold still, and he did.","Turns out people like being asked. Who knew.","Mind the needles on the stump. They're sharper than they look."]),
  'fen-idle': n('fen-idle', 'fen', ["The tally's whole. A roe deer, every morning, down to the creek.","I asked the marten by the split pine something yesterday. She talked for an hour. I may do it again.","Ask me something, if you like. I answer when I'm asked."]),
  'ilsa-idle': n('ilsa-idle', 'ilsa', ["Tomorrow I'm going down to Ivy, my sister. I'll let her feed me.","Don't tell her. She'll make a row of it, and I'll secretly enjoy it.","Sit a while. I'm practising sitting. I'm not much good at it yet."]),
  'skiff-root': n('skiff-root', 'skiff', ["You're the bird from up the valley. Nana's girl.","Look at this. Three feet of ice and no water to float a boat.","I've got a sled up in the rafters. Been there since the freeze. Nobody rides it."], { choices: [c("i'll ride it.", 'skiff-errand', true), c("what's a captain without water?", 'skiff-chat')] }),
  'skiff-chat': n('skiff-chat', 'skiff', ["An otter with a boat in a field. That's what.","The pike are down there somewhere. Sitting in the dark, laughing at me.","I know where they sit. Ask me later if you need to find them."], { next: 'skiff-errand' }),
  'skiff-errand': n('skiff-errand', 'skiff', ["First try the old hill sled. It's left at the top of the boathouse hill. Ride it down once. Mind the birch at the bottom. It doesn't move.","Then find Margit, the raven who counts the ice. She's out there now.","Ask her if it'll hold a sled. And don't let her talk your ear off."], { next: 'skiff-pip' }),
  'skiff-pip': n('skiff-pip', 'pip', ["i'll bring it back in one piece.","the birch, i can't promise."]),
  'skiff-wait': n('skiff-wait', 'skiff', ["Back already? Or did the hill throw you?","Ask the raven, Margit, if the ice holds. She's precise about it.","Come back when you've done both."]),
  'skiff-still': n('skiff-still', 'skiff', ["Down the boathouse hill first. Then ask the raven, Margit, if the ice holds a sled."]),
  'skiff-done': n('skiff-done', 'skiff', ["So the raven says it holds. Good enough for me.","Then mine comes down off the roof. Here. Not a loan: yours, on any slope you like.","Use it hard. That's all a sled wants. Same as a boat."]),
  'skiff-pike': n('skiff-pike', 'skiff', ["Margit, the raven, wants my pike spot? She sent you to ask me?","Fine. Off the end of the old jetty, where the bottom drops away.","They sit there all winter in the dark. Don't tell anyone else.","And tell her I said to write it down right."]),
  'skiff-flour': n('skiff-flour', 'skiff', ["Flour for Orla, up at the bakery? Aye, it's in the hold.","Boat's frozen in, but the hold's dry. Three sacks, sealed in oilcloth.","I'll haul them up the hill by sled this evening. Tell her that.","And tell her I'll want the first loaf. Captain's due."]),
  'skiff-idle': n('skiff-idle', 'skiff', ["Still no water. Still a captain. Somebody has to be.","Ride that sled for me. It's been waiting longer than I have.","Come spring, I'll take you out on real water. You'll see."]),
  'margit-root': n('margit-root', 'margit', ["The ice is forty-one centimetres at the centre. Forty-three at the edge.","The otter with the boat, Skiff, calls that luck. I call it a measurement.","I'm counting today. You fish. Bring me something worth writing down."], { choices: [c("i'll fish.", 'margit-errand', true), c("why count the ice?", 'margit-chat')] }),
  'margit-chat': n('margit-chat', 'margit', ["Because the lake doesn't lie. People do. Numbers don't.","Skiff thinks the ice insulted him. I think it's a record.","Go on. The hole's drilled. I'll count while you pull."], { next: 'margit-errand' }),
  'margit-errand': n('margit-errand', 'margit', ["Fish the hole. I'll count the minutes. Whatever bites, I'll write it down.","Then ask the otter with the boat, Skiff, where the pike sit.","He knows. He just won't say it out loud. Not to me."]),
  'margit-wait': n('margit-wait', 'margit', ["You're back. The hole's still open, and I'm still counting.","Fish it. Then get Skiff to tell you where the pike sit."]),
  'margit-still': n('margit-still', 'margit', ["Fish the hole. I'm counting. Then ask the otter, Skiff, where the pike sit."]),
  'margit-done': n('margit-done', 'margit', ["Off the old jetty? Skiff told you that? He's hoarded it for years.","One fish from my hole, and where the pike sit. That's two lines in the record.","Here's the good bait. Use it off the jetty. Then bring me the next number."]),
  'margit-sled': n('margit-sled', 'margit', ["Skiff, the otter with the boat, wants to know if it holds a sled?","Forty-one centimetres at the centre. It would hold Skiff and his boat.","Tell him yes. Tell him it's a measurement, not luck.","And tell him to stop sulking at the lake. It doesn't notice."]),
  'margit-idle': n('margit-idle', 'margit', ["It's forty-one at the centre, forty-three at the edge. Same as yesterday.","Same is good. Same is a record holding.","Fish if you like. I'll count. I always count."]),
  'orla-root': n('orla-root', 'orla', ["You must be Pip. Sit down, you look frozen through.","The oven's on, but I've no flour. Skiff, the otter with the boat, has it.","Would you ask him for me? And build a snowman while you're out. Keeps your wings warm."], { choices: [c("i'll ask skiff.", 'orla-errand', true), c("why is flour on a boat?", 'orla-chat')] }),
  'orla-chat': n('orla-chat', 'orla', ["Skiff ferries it up the lake each autumn. This year the ice won.","So the sacks sit in his hold, frozen in, and my oven eats wood.","He'll know if any of it's dry. Ask nicely. He sulks about that boat."], { next: 'orla-errand' }),
  'orla-errand': n('orla-errand', 'orla', ["Skiff's boat is iced in, down on the Frozen Reach. He'll know what's aboard.","And the snowman, on the green. Somebody ought to enjoy the snow."], { next: 'orla-pip' }),
  'orla-pip': n('orla-pip', 'pip', ["i'll ask him about the flour.","and build a snowman while i'm at it."]),
  'orla-wait': n('orla-wait', 'orla', ["No flour? Skiff's telling you about the one that got away, I expect.","Take your time. The oven's holding."], { fill: 'orla-snowman' }),
  'orla-done': n('orla-done', 'orla', ["The flour's coming? Tonight? Then the oven stays on.","And there's a snowman on the green, leaning at my window. Yours, I'd bet. It's just right.","Here. Two tins of soup. One for you, one for Nana.","And Skiff wants the first loaf, does he? He'll get it. Thank you, love."]),
  'orla-news': n('orla-news', 'orla', ["Corm, the raven, says we're closed? I've been open since five.","Flour or no flour, the oven's lit. That's open.","Tell him to come and eat something. Then tell him to check his facts."]),
  'orla-blue': n('orla-blue', 'orla', ["Which house is blue? Mine. Look at the door. I painted it in spring.","Pell asks me this every winter. Then he asks somebody else.","Tell him the bakery. Blue door, flour on the step. He can't miss it."]),
  'orla-b': n('orla-b', 'orla', ["I've lit the market lamps for a night bake. Four loaves won't feed this queue.","I'd like a picture of the lamps for the window. And a bell rung when the bread's out.","Gus, who sells bells across the square, has the loudest one. Borrow him for an hour."], { choices: [c("i'll photograph the lamps.", 'orla-berrand', true), c("why gus?", 'orla-bchat')] }),
  'orla-bchat': n('orla-bchat', 'orla', ["He's loud. People hear the bell and know the bread's out.","He'll talk your ear off, but he'll do it."], { next: 'orla-berrand' }),
  'orla-berrand': n('orla-berrand', 'orla', ["Then go and get Gus from his shop, and his bell.","Then come back and tell me the queue's fed."], { fill: 'orla-lamps' }),
  'orla-bwait': n('orla-bwait', 'orla', ["Then go and get Gus from the bell shop, with his bell."], { fill: 'orla-lamps-wait' }),
  'orla-bstill': n('orla-bstill', 'orla', ["Then go and get Gus from the bell shop, with his loud bell."], { fill: 'orla-lamps-still' }),
  'orla-bdone': n('orla-bdone', 'orla', ["Nine loaves. The queue's fed.","You take the credit. I'm going to sit down for five minutes.","Thank you, Pip. Really."]),
  'orla-idle': n('orla-idle', 'orla', ["Nine loaves one day, four the next. Somewhere in between is right.","Sit down, Pip. You look frozen through. There's always a heel of bread.","Tell Nana there's a loaf here whenever she wants one."]),
  'pell-root': n('pell-root', 'pell', ["I've one letter left in the bag, and it's been in there a week.","It says 'The blue house, road head.' I've four blue houses on my round.","I numbered them. It didn't help."], { choices: [c("i'll take the letter.", 'pell-errand', true), c("why four blue houses?", 'pell-chat')] }),
  'pell-chat': n('pell-chat', 'pell', ["Paint fades up here. Frost takes the blue first, then it all goes grey.","So four doors that were blue once. And only one letter.","Nana's cabin at the road head is my best guess. Take it and ask."], { next: 'pell-errand' }),
  'pell-errand': n('pell-errand', 'pell', ["Take the letter down to Hearth Hollow. Give it to Nana at the cabin.","Into her hands, mind. Not the step. Then I'll sleep."], { next: 'pell-pip' }),
  'pell-pip': n('pell-pip', 'pip', ["i'll take it to nana.","she'll know which house is hers."]),
  'pell-wait': n('pell-wait', 'pell', ["Still got it? Nana's cabin is in Hearth Hollow, at the road head.","Into her hands. That's all I ask."]),
  'pell-done': n('pell-done', 'pell', ["You gave it to Nana? And it was the right house?","One letter. One correct delivery. I'll take that.","By her stove, she's keeping it? That's where good letters go. A job done right."], { next: 'pell-b' }),
  'pell-bell': n('pell-bell', 'pell', ["Gus, the bell-seller, wants to know how far his shop bell carries?","I heard it ring just now, from the far end of my round. Clean.","It carries the whole hamlet. Every door I knocked, it got there first.","Tell him the whole hamlet. He'll go pink. Let him."]),
  'pell-news': n('pell-news', 'pell', ["Is the post running? Corm, the raven, sent you to ask? Typical.","Inside the valley, yes. I walk it every morning, door to door.","Over the pass, no. Nothing goes over till the road's cleared.","Tell him both halves. He only ever repeats one."]),
  'pell-b': n('pell-b', 'pell', ["That letter found Nana by luck. The next one might not.","Orla, the mouse with the bakery, knows every door in the hamlet. Ask her which house is blue.","Ivy, the otter who keeps the springs, sees the whole hill from below. Ask her too."], { choices: [c("i'll ask orla.", 'pell-berrand', true), c("why ivy?", 'pell-bchat')] }),
  'pell-bchat': n('pell-bchat', 'pell', ["Ivy sees every house on the hill from the pools. That's her post, in a way.","Orla sees every door from her counter. Between them, they've the whole round."], { next: 'pell-berrand' }),
  'pell-berrand': n('pell-berrand', 'pell', ["Ask Orla which house is blue. Ask Ivy, at the springs, too.","Then come back. I'll have the ledger open."]),
  'pell-bwait': n('pell-bwait', 'pell', ["You're back. The ledger's open. Which house is blue?","Ask Orla, at the bakery, first. Then Ivy, down at Kettle Springs."]),
  'pell-bstill': n('pell-bstill', 'pell', ["Ask Orla, at the bakery, which house is blue. Then Ivy, at the springs. I'll keep the ledger open."]),
  'pell-bdone': n('pell-bdone', 'pell', ["Orla says her door. Ivy says the green one, from where she sits.","Two answers. Both right, from where they stand. No use to a postmaster.","So I'll stop writing colours. I'll write names. Everyone knows a name.","Thank you, Pip. I can sleep now."]),
  'pell-idle': n('pell-idle', 'pell', ["Names on the front now, not colours. Not one letter astray since.","Turns out everybody knows where everybody lives. I only had to ask.","Mind the step. I've sanded it, but it's sneaky."]),
  'gus-root': n('gus-root', 'gus', ["Bells! Bells for sale! ...Oh, you're not buying.","I sell bells. Every size. And I've never once heard the big one ring.","Would you ring my shop bell for me? One clean strike. I want to know how far it goes.","Pell, the postmaster, walks the whole hamlet. Ask him if he heard it."], { choices: [c("i'll ring it.", 'gus-errand', true), c("why not ring the big bell?", 'gus-chat')] }),
  'gus-chat': n('gus-chat', 'gus', ["It's the biggest bell in the valley! Nobody's rung it in years.","What if I pull the rope and it goes clunk? In front of everyone?","So. The shop bell first. If that carries, maybe the big one will."], { next: 'gus-errand' }),
  'gus-errand': n('gus-errand', 'gus', ["Then ask Pell how far the sound travelled. He'll know. He hears every door."], { fill: 'gus-ring' }),
  'gus-wait': n('gus-wait', 'gus', ["Then ask Pell, out on his round, how far it carried."], { fill: 'gus-ring-wait' }),
  'gus-still': n('gus-still', 'gus', ["Then ask Pell, the postmaster, how far it carried."], { fill: 'gus-ring-still' }),
  'gus-done': n('gus-done', 'gus', ["It carries the hamlet? The whole hamlet?","Then the big bell could reach the valley. I've got to try it. Soon. Fairly soon.","Here, take these. Bells for your trouble. Spend them on my feathers. They buy you breath."]),
  'gus-bake': n('gus-bake', 'gus', ["Orla, at the bakery, wants me? For an hour? To ring?","I'll ring for bread any day. Loaves out, bell rings, queue comes.","Lock the shop? No. Nobody steals bells. They'd be heard.","Tell her I'm on my way. Bringing the loud one."]),
  'gus-idle': n('gus-idle', 'gus', ["Bells! Bells for sale! ...Oh, it's you. Hello.","I'm working up to the big bell. I've held the rope. That's a start.","One day I'll pull it, and the whole valley will hear. You'll see.","Those two feathers by my feet are forty bells each. Longer breath for the climb."]),
  'ivy-root': n('ivy-root', 'ivy', ["Don't splash. I'm Ivy. I keep the pools, and the pools are going cold.","Two degrees down since the first snow. Everyone says it's the weather.","It isn't. It's the stone dam on the low pool. Somebody's been knocking stones out of it."], { choices: [c("who'd knock stones out?", 'ivy-chat'), c("what can i do?", 'ivy-errand')] }),
  'ivy-chat': n('ivy-chat', 'ivy', ["Whoever comes off the otter slide too fast. I'm not naming anyone.","Every slider who hits the dam takes a stone with them, and the warm water goes out the gap.","Eleven winters I've kept these pools. I'm not losing them to somebody's fun."], { next: 'ivy-errand' }),
  'ivy-errand': n('ivy-errand', 'ivy', ["Then get the temperature off Corm, the raven by the steam. The glass is on his rock.","He's sat beside it a whole year and never once read it. Make him read it.","I want a number. Not news."], { fill: 'ivy-dam' }),
  'ivy-wait': n('ivy-wait', 'ivy', ["Then Corm, on his rock by the steam. Make him read the glass.","A number, mind. Not something he heard."], { fill: 'ivy-dam-wait' }),
  'ivy-done': n('ivy-done', 'ivy', ["Forty-one. Off the glass? Corm actually read it?","That's up on last week. The dam's holding. Listen to that steam.","Here. A warm stone from the bottom of the pool. Keep it in a pocket.","And if you see my sister, don't tell her I was worried."]),
  'ivy-bundle': n('ivy-bundle', 'ivy', ["From Ilsa, my sister? She sent it with you instead of coming.","Don't say we don't look alike. Everyone says it.","She'd carry the whole valley before she'd knock on my door. Dried apples. Her good scarf.","Tell her it landed. And to come down herself next time. I'll feed her."]),
  'ivy-blue': n('ivy-blue', 'ivy', ["Which house is blue? From down here, the one with the green door.","At dusk the steam turns everything up the hill blue. That one most.","Pell, the postmaster, should come down and look. He never comes down."]),
  'ivy-idle': n('ivy-idle', 'ivy', ["Forty-one and holding. The dam's doing its job.","If you see my sister in the pines, say the pools are warm. Don't say I said it.","Soak your feet before you go. Everyone's feet are cold this time of year."]),
  'corm-root': n('corm-root', 'corm', ["News! You'll want the news. I'm Corm. I hear it all, and I pass it on.","Word is the bakery in Hollowpine Hamlet is shut. Also, word is it's open.","Word is the post's stopped. Also, it's running. I've been saying all four since breakfast."], { choices: [c("which is true?", 'corm-chat'), c("have you checked?", 'corm-check')] }),
  'corm-chat': n('corm-chat', 'corm', ["No idea! That's the trouble. I say what I hear, and I hear everything.","Just once I'd like to say a thing and have it be true."], { next: 'corm-errand' }),
  'corm-check': n('corm-check', 'corm', ["Checked? I'd have to go and ask. People look at you funny when you ask.","Hearing's easier. Hearing comes to you."], { next: 'corm-errand' }),
  'corm-errand': n('corm-errand', 'corm', ["Orla, who runs the bakery, would know if it's open.","Pell, the postmaster, would know if the post's running.","Ask them for me? Then come back and give it to me straight. I'll pass it on right, for once."]),
  'corm-wait': n('corm-wait', 'corm', ["Back? With news? No? Orla first, at the bakery. Is it open?","Then Pell, the postmaster. Is the post running?","Then me. Slowly. I want to get it right."]),
  'corm-still': n('corm-still', 'corm', ["Orla, at the bakery: is it open? Pell, the postmaster: is the post running? Then back to me."]),
  'corm-done': n('corm-done', 'corm', ["The bakery's open. Post runs inside the valley. Nothing goes over the pass.","And all of it true? Checked? By somebody who asked?","Well. I'll pass that on, every word. I could get used to this.","Here, for your trouble. That's not hearsay. That's bells."]),
  'corm-temp': n('corm-temp', 'corm', ["The pool temperature? I heard it was freezing. Jory, the mouse, told me so.","Ivy wants a reading? Off the glass? Not what I heard?","Fine. The glass is right here. I've never once read it. ...Forty-one.","Tell her forty-one. First thing I've ever checked. It felt strange."]),
  'corm-idle': n('corm-idle', 'corm', ["I've checked things this week. Actual things. It's exhausting.","The bakery's open. The post runs inside the valley. Both true. Somebody asked.","Bring me anything you hear. I'll check it. Probably."]),
  'jory-root': n('jory-root', 'jory', ["I have lived at Kettle Springs my whole life. I have never been cold.","The warm pool keeps the chill off. That is the whole reason I stay.","The pines are not far. I have heard they are not far.","I would like to go as far as the pines. Once. And come back."], { choices: [c("i could go first.", 'jory-errand', true), c("why the pines?", 'jory-chat')] }),
  'jory-chat': n('jory-chat', 'jory', ["The pines are where the cold starts. Everyone says so.","I have never felt it. I think I would like to know.","Or maybe I would not. I am not sure. Would you go first?"], { next: 'jory-errand' }),
  'jory-errand': n('jory-errand', 'jory', ["Then catch me a fish from the warm pool first. For the walk, when I go. A mouse takes lunch.","Then walk to Pinewind Wood for me. Go first, and look at it properly.","Come back and tell me what it is like. Then I will decide."]),
  'jory-wait': n('jory-wait', 'jory', ["You are still going? Good. I am still here. I have not moved.","A fish from the warm pool first. Then the pines, in Pinewind Wood.","Then tell me what they are like. All of it. The cold too."]),
  'jory-done': n('jory-done', 'jory', ["The pines are like that? Tall, and creaking, and the snow is quiet?","And it was cold, but you came back. You are standing right here.","And the fish. I have it wrapped in a leaf, for the walk. I checked it twice.","Then I think I can go. Not today. Tomorrow. As far as the pines.","Here. For going first. I am not good at thank you."]),
  'jory-idle': n('jory-idle', 'jory', ["I put one foot out of the warm pool this morning. Then both.","It was cold. I stood and counted to forty. Then I got back in.","Tomorrow I will count to fifty. Then the pines. You will see."]),
  'tuck-root': n('tuck-root', 'tuck', ["Careful on the planks. I'm Tuck. I keep this bridge.","I tie it, I tighten it, I check it every hour. I don't cross it. Different job.","The rope's going. See the fraying there? Another storm and it parts."], { choices: [c("why don't you cross it?", 'tuck-chat'), c("i've brought you rope.", 'tuck-rope-seen')] }),
  'tuck-rope-seen': n('tuck-rope-seen', 'tuck', ["Hold on. Is that Bram's good rope? From the woodstore by the big pine?","He sent it up? With you? He hasn't said a word to me in years."], { next: 'tuck-done' }),
  'tuck-chat': n('tuck-chat', 'tuck', ["Somebody has to stand at this end and watch the knots hold. That's me.","Sable, the fox at the wind post, says I'm scared. Sable files reports. I tie knots.","We'll leave it there."], { next: 'tuck-rope-seen' }),
  'tuck-done': n('tuck-done', 'tuck', ["Forty feet, no splices. He measured it before he gave it you, didn't he.","There. Tied, tightened, tested. It'll hold a storm.","Tell Bram it's still forty feet. Not an inch off. He can come up and measure it himself.","I didn't cross it. I didn't need to.","Here. I found this tied into the old rope years back. Show Bram. He'll know it."]),
  'tuck-chimney': n('tuck-chimney', 'tuck', ["Nettle Chimney is climbable? The tall face past the bridge? You went up it?","Then there's a way up this ridge that isn't a bridge.","I've never said I wouldn't climb. Only that I wouldn't cross.","Tell Sable I'm thinking about it. Just thinking."]),
  'tuck-idle': n('tuck-idle', 'tuck', ["I check this bridge every hour. I don't cross it. Different job.","Wind's up. Rope doesn't mind wind. It minds age.","Mind the planks on your way over. I mean that kindly."]),
  'sable-root': n('sable-root', 'sable', ["Sable, wind post, Windscar Ridge. I measure the wind and file a report, whatever it says.","Today's report so far reads 'windy'. That won't do.","I need two readings: one high, one low. The kite gets me the high one, over the crest.","The lantern ascent gets me the low one. I read the wind off the flames as you pass them."], { choices: [c("why file it either way?", 'sable-chat'), c("i'll get your readings.", 'sable-errand', true)] }),
  'sable-chat': n('sable-chat', 'sable', ["A report that only files the good days is a lie with a stamp on it.","Tuck, the marten at the bridge, says the wind will take his bridge one day. I say the rope will.","One of us will be right. I'll file it either way."], { next: 'sable-errand' }),
  'sable-errand': n('sable-errand', 'sable', ["The kite goes first. Get it up off the crest, above the ridge line.","Then run the lantern ascent, gate to gate. I'll watch the flames from here.","Then come back, and I'll write it up."]),
  'sable-wait': n('sable-wait', 'sable', ["The report's still blank. Kite above the crest, please.","Then the lantern ascent, up the ridge. Then back to me."]),
  'sable-done': n('sable-done', 'sable', ["Kite reading: forty, gusting. Lantern reading: the same, lower down. Consistent.","That's a report worth filing. I'll stamp it twice.","For the record, the bridge stood through all of it. Don't tell Tuck I wrote that.","Here. For the readings."]),
  'sable-b': n('sable-b', 'sable', ["I've a new question. It's been on my desk a year.","Nettle Chimney is the tall face on this ridge. Nobody's tried it. I want it on the record.","Take the chimney scramble to the top. Then tell Tuck the face is climbable.","He won't cross a bridge. He's never said a word about climbing. Then come and tell me."]),
  'sable-bwait': n('sable-bwait', 'sable', ["The chimney's still not on the record. Take the scramble to the top.","Then Tuck. Then me. I'll file it either way."]),
  'sable-bdone': n('sable-bdone', 'sable', ["Climbable. Witnessed. I'll file it.","And Tuck's thinking about it? Tuck's never thought about anything but knots.","Two ways up this ridge now. One for crossers. One for climbers.","Here. For the climb. I'll race you up it next time."]),
  'sable-idle': n('sable-idle', 'sable', ["Forty, gusting. Filed. I file everything.","Somebody keeps lighting the lanterns on the ridge. Good. I like a flicker.","Mind the crest. The wind doesn't file reports. It just pushes."]),
};
